import{_ as i,c as r,o as t,ag as l}from"./chunks/framework.BtwP-r-R.js";const a="/14B-POO-A26/assets/exercice_liste_generique.njWfnhsa.png",o="/14B-POO-A26/assets/formGestionFilm.D5FWR0ST.png",s="/14B-POO-A26/assets/formDetailFilm.DRQh871R.png",b=JSON.parse('{"title":"Exercices bloc 2","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"exercices_bloc2.md","filePath":"exercices_bloc2.md"}'),n={name:"exercices_bloc2.md"};function u(m,e,d,c,p,f){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="exercices-bloc-2" tabindex="-1">Exercices bloc 2 <a class="header-anchor" href="#exercices-bloc-2" aria-label="Permalink to &quot;Exercices bloc 2&quot;">​</a></h1><h2 id="semaine-7" tabindex="-1">Semaine 7 <a class="header-anchor" href="#semaine-7" aria-label="Permalink to &quot;Semaine 7&quot;">​</a></h2><details class="details custom-block"><summary>Liste génériques</summary><h3 id="liste-generiques" tabindex="-1">Liste génériques <a class="header-anchor" href="#liste-generiques" aria-label="Permalink to &quot;Liste génériques&quot;">​</a></h3><p>Mettre en pratique la création d&#39;interfaces en WPF et l&#39;utilisation de la liste générique.</p><h4 id="probleme" tabindex="-1">Problème <a class="header-anchor" href="#probleme" aria-label="Permalink to &quot;Problème&quot;">​</a></h4><ol><li><p>Créer un nouveau projet WPF nommé <strong>S7E1_ExerciceListeGenerique</strong>.</p></li><li><p>Créer la classe <strong>Film</strong> répondant aux spécifications suivantes :</p><ul><li><strong>Attributs et propriétés</strong> : <ul><li>Id (Identifiant unique)</li><li>Titre (Ne doit pas être vide)</li><li>Année (Doit être supérieur à 1888 et inférieure ou égale à l&#39;année courante)</li></ul></li><li><strong>Constructeur</strong><ul><li>Avec paramètre permettant d&#39;initialiser l&#39;id, le titre et l&#39;année du film.</li></ul></li><li><strong>Méthodes</strong> : <ul><li>ToString() : Retourne le titre du film avec l&#39;année entre parenthèses.</li></ul></li></ul></li><li><p>Créer une classe nommée GestionFilms permettant la gestion d’une liste de film.</p><ul><li><strong>Attributs et propriétés</strong> : <ul><li>Liste de films (set privé).</li></ul></li><li><strong>Constructeur</strong><ul><li>Sans paramètre permettant d’initialiser une liste de films vide.</li></ul></li><li><strong>Méthodes</strong><ul><li><strong>bool AjouterFilm(Film pFilm)</strong> : Permet l’ajout du film à la liste de film. Un film ne peut pas être ajouté s’il existe déjà un film ayant le même titre et la même année dans la liste. Retourne vraie si le film a été ajouté, faux sinon.</li><li><strong>bool SupprimerFilm(Film pFilm)</strong> : Permet la suppression du film de la liste de films. Retourne vraie si le film a été trouvé et supprimé, faux sinon.</li></ul></li></ul></li><li><p>Créer l&#39;interface suivante</p></li></ol><p><img src="'+a+'" alt="Interface de gestion des films"></p><ul><li>Ajouter un attribut de type GestionFilm nommé <strong>_gestionFilms</strong> dans votre formulaire. Celui-ci vous permettra de gérer les films.</li><li>Écrire le code du formulaire permettant : <ul><li>D&#39;initialiser le formulaire en cliquant sur le bouton Nouveau. L&#39;initialisation doit supprimer le contenu des champs, désactiver le bouton supprimer et activer le bouton ajouter.</li><li>De valider le formulaire. Tous les champs sont obligatoires. L&#39;année doit être inférieure à la date du jour. Vous pouvez utiliser DateTime.Now.Year pour obtenir l&#39;année courante. Vous devez afficher toutes les erreurs à l&#39;utilisateur si le formulaire n&#39;est pas valide.</li><li>D&#39;ajouter un nouveau film valide à la liste des films contenus dans votre attribut <strong>_gestionFilms</strong>. N&#39;oubliez pas de donner une rétroaction à l&#39;utilisateur si l&#39;ajout a fonctionné ou non. Vous devez mettre à jour le ListBox.</li><li>D&#39;afficher la listes des films contenus dans l&#39;attribut <strong>_gestionFilms</strong></li><li>De sélectionner un film dans le ListeBox et d&#39;afficher les informations d&#39;un film dans les champs texte. Lors d&#39;une sélection, le bouton ajouter est désactivé et le bouton supprimé est activé.</li><li>De supprimer un film sélectionné dans la liste de la liste des films contenue dans l&#39;attribut <strong>_gestionFilm</strong>. Vous devez demander à l&#39;utilisateur de confirmer la suppression avant d&#39;effectuer l&#39;action. N&#39;oubliez pas de donner une rétroaction à l&#39;utilisateur si la suppression a fonctionné ou non. Vous devez mettre à jour le ListBox.</li><li>Permettre de fermer le formulaire avec le bouton quitter.</li></ul></li></ul><h4 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;Solution&quot;">​</a></h4><p>Télécharger la solution commplète : <a href="https://gitlab.com/420-14b-fx/contenu/-/raw/main/bloc2/cours%2013/S7E1-ListeGenerique%20-%20Solution.zip?ref_type=heads" target="_blank" rel="noreferrer">S7E1-ListeGeneriqe-Solution</a></p></details><details class="details custom-block"><summary>Formulaire secondaire</summary><h3 id="formulaire-secondaire" tabindex="-1">Formulaire secondaire <a class="header-anchor" href="#formulaire-secondaire" aria-label="Permalink to &quot;Formulaire secondaire&quot;">​</a></h3><h3 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h3><p>Mettre en pratique la création d&#39;interfaces en WPF avec plusieurs formulaires et l&#39;utilisation de la liste générique.</p><h3 id="probleme-1" tabindex="-1">Problème <a class="header-anchor" href="#probleme-1" aria-label="Permalink to &quot;Problème&quot;">​</a></h3><ol><li><p>Créer un nouveau projet WPF nommé S7E2_Formulaire secondaire.</p></li><li><p>Créer la classe Film (vous pouvez réutiliser la classe de l&#39;exercice précédent) répondant aux spécifications suivantes :</p><ul><li><strong>Attributs et propriétés</strong> : <ul><li>Titre : Ne peut pas être vide. Si tel est la cas, alors la valeur est &quot;Non fourni&quot;.</li><li>Année : Doit être entre 1888 et l&#39;année courante. Si est invérieur à 1888 alors la valeur est 1888 et si est supérieur à l&#39;année courante alors la valeur est l&#39;année courante.</li><li>Acteurs (liste de chaîne de caractères)</li></ul></li><li><strong>Constructeur</strong><ul><li>Avec paramètre permettant d&#39;initialiser le titre et l&#39;année du film ainsi qu&#39;une liste d&#39;acteur vide.</li></ul></li><li><strong>Méthodes</strong> : <ul><li>ToString() : Retourne le titre du film avec l&#39;année entre parenthèses.</li></ul></li></ul></li><li><p>Créer une classe nommée GestionFilms permettant la gestion d’une liste de film. (Vous pouvez réutiliser celle créer dans l&#39;exercice précédent)</p><ul><li><strong>Attributs et propriétés</strong> : <ul><li>Liste de films (set privé).</li></ul></li><li><strong>Constructeur</strong><ul><li>Sans paramètre permettant d’initialiser une liste de films vide.</li></ul></li><li><strong>Méthodes</strong><ul><li>bool AjouterFilm(Film pFilm) : Permet l’ajout du film à la liste de film. Un film ne peut pas être ajouté s’il existe déjà un film ayant le même titre et la même année dans la liste. Retourne vraie si le film a été ajouté, faux sinon.</li><li>bool SupprimerFilm(Film pFilm) : Permet la suppression du film de la liste de films. Retourne vraie si le film a été trouvé et supprimé, faux sinon.</li></ul></li></ul></li><li><p>Créer l&#39;interface suivante dans le formulaire principal.</p></li></ol><p><img src="'+o+'" alt="Formulaire gestion films"></p><ul><li>Ajouter un attribut de type GestionFilms dans votre formulaire et l’instancier dans la méthode « Window_Loaded » du formulaire. Celui-ci vous permettra de gérer les films.</li><li>Écrire le code du formulaire permettant : <ul><li>Lors du chargement du formulaire. Ajouter le film suivant à votre attribut de type GestionFilms ainsi qu&#39;un film de votre choix : <ul><li>Titre: Spider-man No way hom</li><li>Année: 2021</li><li>Acteurs: Tome Holland, Zendaya Colman</li></ul></li><li>Afficher la liste de film dans le ListBox.</li></ul></li></ul><ol start="5"><li>Ajouter et créer l&#39;interface d&#39;un nouveau formulaire nommé <strong>FormFilm</strong> à votre projet:</li></ol><p><img src="'+s+'" alt="Formulaire détails d&#39;un film"></p><ul><li>Écrire le code du formulaire permettant : <ul><li>D&#39;afficher les détails du film sélectionné dans le formulaire parent.</li><li>Fermer le formulaire lors du clique du bouton Fermer.</li></ul></li></ul><ol start="6"><li>Écrire le code du bouton « Afficher détails » du formulaire principal permettant d&#39;afficher les détails d&#39;un film sélectionné dans le formulaire FormFilm.</li></ol><h4 id="solution-1" tabindex="-1">Solution <a class="header-anchor" href="#solution-1" aria-label="Permalink to &quot;Solution&quot;">​</a></h4><p>Télécharger la solution commplète : <a href="https://gitlab.com/420-14b-fx/contenu/-/raw/main/bloc2/cours%2014/S7E2-FormulaireSecondaire.zip?ref_type=heads" target="_blank" rel="noreferrer">S7E2-FormulaireSecondaire-Solution</a></p></details><h2 id="semaine-8" tabindex="-1">Semaine 8 <a class="header-anchor" href="#semaine-8" aria-label="Permalink to &quot;Semaine 8&quot;">​</a></h2><details class="details custom-block"><summary>S8E1 - Application Windows multiformulaires</summary><h3 id="objectif-1" tabindex="-1">Objectif <a class="header-anchor" href="#objectif-1" aria-label="Permalink to &quot;Objectif&quot;">​</a></h3><p>Mettre en pratique la construction d&#39;une application Windows multiformulaires permettant d&#39;effectuer les opérations classiques sur des données, soient créer/ajouter (<strong>C</strong>reate), lire/consulter (<strong>R</strong>ead), mettre à jour/modifier (<strong>U</strong>pdate), supprimer/détruire (<strong>D</strong>elete). On utilise souvent l&#39;acronyme CRUD en anglais pour désigner cet ensemble d&#39;opérations très courant en informatique de gestion.</p><h3 id="probleme-2" tabindex="-1">Problème <a class="header-anchor" href="#probleme-2" aria-label="Permalink to &quot;Problème&quot;">​</a></h3><p>Télécharger la démonstration présentée en classe : <a href="https://gitlab.com/420-14b-fx/contenu/-/raw/main/bloc2/cours%2015/S8C1-DemoCRUD%20-%20Create.zip?ref_type=heads" target="_blank" rel="noreferrer">S8C1-DemoCRUD</a></p><p>Implémentant la <strong>modification</strong> et la <strong>suppression</strong> d&#39;un employé.</p><ul><li>Pour la modification, vous devez <strong>modifier le formulaire existant</strong> afin qu&#39;il affiche les informations d&#39;un employé sélectionné et permette la modification. Assurez-vous de bien modifier le titre de du formulaire ainsi que le libellé des boutons.</li><li>Pour la suppression, vous devez <strong>modifier le formulaire existant</strong> pour qu&#39;il affiche les informations de l&#39;employé en lecture seule seulement. Vous devez également demander la confirmation par l&#39;utilisateur avant la suppression. Assurez-vous de bien modifier le titre de du formulaire ainsi que le libellé des boutons.</li></ul><p>À la suite d&#39;une de ces opérations, faites-en sorte que la liste des employés soit modifiée ainsi que le ListBox présentant les employés.</p></details><h2 id="semaine-9" tabindex="-1">Semaine 9 <a class="header-anchor" href="#semaine-9" aria-label="Permalink to &quot;Semaine 9&quot;">​</a></h2><details class="details custom-block"><summary>Surcharge d&#39;opérateurs</summary><h3 id="surcharge-d-operateurs" tabindex="-1">Surcharge d&#39;opérateurs <a class="header-anchor" href="#surcharge-d-operateurs" aria-label="Permalink to &quot;Surcharge d&#39;opérateurs&quot;">​</a></h3><h3 id="objectif-2" tabindex="-1">Objectif <a class="header-anchor" href="#objectif-2" aria-label="Permalink to &quot;Objectif&quot;">​</a></h3><p>Mettre en pratique la surcharge des opérateurs.e.</p><h3 id="probleme-3" tabindex="-1">Problème <a class="header-anchor" href="#probleme-3" aria-label="Permalink to &quot;Problème&quot;">​</a></h3><p>Vous devez créer une classe Matrice qui représente une matrice bidimensionnelle. Ensuite, vous devez surcharger les opérateurs + et - pour permettre l&#39;addition et la soustraction de matrices. De plus, vous devez surcharger l&#39;opérateur * pour permettre la multiplication d&#39;une matrice par un nombre.</p><ol><li><p>Créez une classe Matrice avec un attribut qui est une matrice bidimensionnelle (un tableau 2D) pour stocker les éléments de la matrice ainsi que deux propriétés en lecture seule permettant d&#39;obtenir le nombre de lignes et de colonnes de la matrice.</p></li><li><p>Créez une méthode publique permettant d&#39;obtenir une valeure de la matrice selon une ligne et une colonne reçue en paramètres.</p></li><li><p>Créer une méthode publique permettant de modifier une valeur de la matrice à une position à partir de la ligne, de la colonne et de la valeur reçues en paramètres.</p></li><li><p>Surchargez les opérateurs + et - pour permettre l&#39;addition et la soustraction de matrices. Les opérations devraient créer une nouvelle matrice résultante avec les éléments corrects. So l&#39;une des deux matrices est null, alors la valeur null est retournée. Si les deux matrices n&#39;ont pas le même nombre de lignes et de colonnes la valeur null est retournée.</p></li><li><p>Surchargez l&#39;opérateur * pour permettre la multiplication d&#39;une matrice par un scalaire. L&#39;opération devrait créer une nouvelle matrice résultante avec tous les éléments multipliés par le scalaire donné. Si la matrice est null alors la valeur null est retournée.</p></li><li><p>Surchargez l&#39;opérateur * pour permettre la multiplication d&#39;un scalaire par une matrice. L&#39;opération devrait créer une nouvelle matrice résultante avec tous les éléments multipliés par le scalaire donné. Si la matrice est null alors la valeur null est retournée.</p></li><li><p>Créer la méthode ToString() permettant de retourner la représentation sous forme de chaîne de caratères d&#39;une matrice.</p></li><li><p>Écrivez un programme principal (Main) pour tester votre classe Matrix et les opérations de surcharge d&#39;opérateurs. Créez quelques matrices, effectuez des opérations d&#39;addition, de soustraction et de multiplication par un scalaire, puis affichez les résultats.</p></li></ol></details>',8)])])}const g=i(n,[["render",u]]);export{b as __pageData,g as default};
